From 81cdc757de1b00ccf80f645e94694423bdae8bf2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:21:59 +0100
Subject: [PATCH] applet, kded: offer connecting with the router's WPS button

NetworkManager can join a Wi-Fi network through push-button WPS, but
Plasma never let people start it nor told them about it. The applet now
offers it below the password field and the password dialog mentions it.

BUG: 459277
---
 applet/ConnectionItem.qml | 27 +++++++++++++++++++++++++++
 kded/passworddialog.cpp   | 12 +++++++++++-
 libs/handler.cpp          | 23 +++++++++++++++++++++++
 libs/handler.h            |  8 ++++++++
 4 files changed, 69 insertions(+), 1 deletion(-)

diff --git a/applet/ConnectionItem.qml b/applet/ConnectionItem.qml
index e2a79fd2f..f2b66e2e9 100644
--- a/applet/ConnectionItem.qml
+++ b/applet/ConnectionItem.qml
@@ -254,6 +254,33 @@ PlasmaExtras.ExpandableListItem {
                     setDelayModelUpdates(true)
                 }
             }
+
+            PlasmaComponents3.Button {
+                id: wpsButton
+
+                Layout.leftMargin: Kirigami.Units.gridUnit
+                Layout.rightMargin: Kirigami.Units.gridUnit
+                visible: false
+
+                text: i18nc("@action:button", "Connect Using Router's WPS Button")
+
+                onClicked: {
+                    handler.addAndActivateConnection(connectionItem.model.DevicePath, connectionItem.model.SpecificPath)
+                    connectionItem.customExpandedViewContent = detailsComponent
+                    connectionItem.collapse()
+                }
+
+                Connections {
+                    target: handler
+                    function onWpsPushButtonSupportReceived(accessPoint: string, supported: bool): void {
+                        if (accessPoint === connectionItem.model.SpecificPath) {
+                            wpsButton.visible = supported
+                        }
+                    }
+                }
+
+                Component.onCompleted: handler.requestWpsPushButtonSupport(connectionItem.model.SpecificPath)
+            }
         }
     }

