             }
diff --git a/libs/handler.cpp b/libs/handler.cpp
index 1a8d79746..0fb9f08fd 100644
--- a/libs/handler.cpp
+++ b/libs/handler.cpp
@@ -756,6 +756,29 @@ QCoro::Task<> Handler::requestScanInternal(const QString &iface)
     }
 }

+void Handler::requestWpsPushButtonSupport(const QString &accessPoint)
+{
+    requestWpsPushButtonSupportInternal(accessPoint);
+}
+
+QCoro::Task<> Handler::requestWpsPushButtonSupportInternal(const QString &ap)
+{
+    // we can't keep a reference across a co_await
+    const QString accessPoint = ap;
+
+    QDBusMessage message =
+        QDBusMessage::createMethodCall(QStringLiteral(NM_DBUS_SERVICE), accessPoint, QStringLiteral("org.freedesktop.DBus.Properties"), QStringLiteral("Get"));
+    message << QStringLiteral(NM_DBUS_INTERFACE_ACCESS_POINT) << QStringLiteral("Flags");
+
+    QPointer<Handler> thisGuard(this);
+    const QDBusReply<QDBusVariant> reply = co_await QDBusConnection::systemBus().asyncCall(message);
+    if (!thisGuard) {
+        co_return;
+    }
+
+    Q_EMIT wpsPushButtonSupportReceived(accessPoint, reply.isValid() && (reply.value().variant().toUInt() & NM_802_11_AP_FLAGS_WPS_PBC));
+}
+
 void Handler::incrementScansCount()
 {
     m_ongoingScansCount += 1;
